// Verifies the HMAC signature Convex puts on every loan event, rejects stale
// or replayed requests, and keeps only the fields the notification needs.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;
// Convex signs the method and path it posts to, so a signature made for any
// other endpoint fails here. Keep in sync with this workflow's webhook path.
const WEBHOOK_PATH = '/webhook/lendloop-loan-events';

const secret = $env.LENDLOOP_TO_N8N_SECRET;
if (!secret) throw new Error('LENDLOOP_TO_N8N_SECRET is not configured');

const item = $input.first();
const headers = item.json.headers || {};
// The Webhook node keeps the exact bytes Convex signed (Raw Body option).
const rawBody = item.binary && item.binary.data
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')
  : JSON.stringify(item.json.body);

const reject = (httpStatus, reason) => [{ json: { accepted: false, httpStatus, response: { error: reason } } }];

const timestamp = Number(headers['x-lendloop-timestamp']);
const signature = String(headers['x-lendloop-signature'] || '');
if (!Number.isInteger(timestamp) || !signature) return reject(401, 'invalid signature');
if (Math.abs(Date.now() / 1000 - timestamp) > MAX_SKEW_SECONDS) return reject(401, 'invalid signature');

const expected = 'v2=' + crypto
  .createHmac('sha256', secret)
  .update([timestamp, 'POST', WEBHOOK_PATH, rawBody].join('\n'))
  .digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signature);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject(401, 'invalid signature');

let event;
try { event = JSON.parse(rawBody); } catch { return reject(400, 'invalid body'); }

// Convex retries until it gets a 2xx, so the same event can arrive twice.
// Remember delivered event ids (production executions persist static data).
const seen = $getWorkflowStaticData('global').deliveredEventIds || [];
if (seen.includes(event.eventId)) {
  return [{ json: { accepted: false, httpStatus: 200, response: { status: 'duplicate', eventId: event.eventId } } }];
}

return [{
  json: {
    accepted: true,
    eventId: event.eventId,
    type: event.type,
    recipient: event.recipient,
    counterpartName: event.counterpartName,
    loan: event.loan,
  },
}];

// Turns a loan event into a short, friendly message.
const fmt = (iso) => new Date(iso + 'T00:00:00Z').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });

return $input.all().map(({ json: e }) => {
  const tool = e.loan.toolName;
  const dates = e.loan.startDate === e.loan.endDate ? fmt(e.loan.startDate) : `${fmt(e.loan.startDate)}–${fmt(e.loan.endDate)}`;
  const who = e.counterpartName;
  const messages = {
    'loan.requested': [`New request for your ${tool}`, `${who} would like to borrow your ${tool} (${dates}). Open LendLoop to approve or decline.`],
    'loan.approved': [`Request approved: ${tool}`, `Good news! ${who} approved your request to borrow the ${tool} (${dates}).`],
    'loan.declined': [`Request declined: ${tool}`, `${who} can't lend the ${tool} for ${dates} this time.`],
    'loan.cancelled': [`Request cancelled: ${tool}`, `${who} cancelled their request for your ${tool} (${dates}).`],
    'loan.returned': [`Thanks for returning the ${tool}`, `${who} confirmed the ${tool} is back. Thanks for being a good neighbour!`],
    'loan.listing_removed': [`Listing removed: ${tool}`, `The ${tool} is no longer listed, so your request for ${dates} was cancelled.`],
  };
  const [subject, text] = messages[e.type] || [`Update on ${tool}`, `Your loan of the ${tool} is now ${e.loan.status}.`];
  return {
    json: {
      eventId: e.eventId,
      to: e.recipient.email,
      greeting: `Hi ${e.recipient.name},`,
      subject,
      text,
    },
  };
});

// MOCK CHANNEL. Swap this node for Send Email / Slack / Discord in production;
// the message already contains only what the recipient needs.
// Set SIMULATE_NOTIFY_FAILURE=true on the container to exercise retries and the
// error workflow end to end.
if ($env.SIMULATE_NOTIFY_FAILURE === 'true') {
  throw new Error('Simulated notification channel outage');
}

return $input.all().map(({ json: m }) => {
  // Log a masked address: execution logs shouldn't become a contact list.
  const masked = m.to ? m.to.replace(/^(.).*(@.*)$/, '$1***$2') : '(no email on file)';
  console.log(`[lendloop] notify ${masked}: ${m.subject}`);
  return { json: { eventId: m.eventId, channel: 'mock', delivered: true, to: masked, subject: m.subject } };
});

// Record delivery so a Convex retry of the same event is acknowledged without
// notifying the user twice. Keep a bounded window of recent ids.
const data = $getWorkflowStaticData('global');
const seen = data.deliveredEventIds || [];
for (const { json } of $input.all()) seen.push(json.eventId);
data.deliveredEventIds = seen.slice(-1000);

return [{ json: { httpStatus: 200, response: { status: 'delivered', eventIds: $input.all().map((i) => i.json.eventId) } } }];
